// Generated by `tsir make:policy`. Verifies the `user.delete` policy rule
// allows principals whose role grants `user.delete` and denies everyone else.
import { describe, expect, test } from 'bun:test';

import { userDeletePolicy, userDeleteRule } from './user-delete.policy.ts';

describe('user.delete policy', () => {
  test('is registered under the user:delete ref', () => {
    expect(userDeletePolicy[0]).toBe('user:delete');
  });

  test('allows when the permission is granted', () => {
    const decision = userDeleteRule({
      principal: { subject: 'u_1' },
      data: undefined,
      permissions: new Set(['user.delete']),
    });
    expect(decision.allowed).toBe(true);
  });

  test('denies when the permission is not granted', () => {
    const decision = userDeleteRule({
      principal: { subject: 'u_1' },
      data: undefined,
      permissions: new Set(),
    });
    expect(decision.allowed).toBe(false);
  });
});
